namespace Aegis.Studio.Domain.Galleries;
public sealed class PrintJob{private PrintJob(){} public PrintJob(Guid mediaAssetId,Guid workspaceId,string requestedBy,int quantity,string specification,DateTimeOffset scheduledUtc){Id=Guid.NewGuid();MediaAssetId=mediaAssetId;WorkspaceId=workspaceId;RequestedBy=requestedBy.Trim();Quantity=quantity;Specification=specification.Trim();ScheduledUtc=scheduledUtc;Status="Scheduled";CreatedUtc=DateTimeOffset.UtcNow;} public Guid Id{get;private set;} public Guid MediaAssetId{get;private set;} public Guid WorkspaceId{get;private set;} public string RequestedBy{get;private set;}=string.Empty; public int Quantity{get;private set;} public string Specification{get;private set;}=string.Empty; public DateTimeOffset ScheduledUtc{get;private set;} public string Status{get;private set;}=string.Empty; public DateTimeOffset CreatedUtc{get;private set;} public void Complete()=>Status="Completed";}
